import fs from 'node:fs';import assert from 'node:assert/strict';import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),orig=db._request.bind(db);
db._request=async p=>{assert.ok(['all','first'].includes(p.op)&&/^\s*(SELECT|EXPLAIN QUERY PLAN|PRAGMA (page_count|page_size|freelist_count))\b/i.test(p.sql)&&!/(INSERT|DELETE|UPDATE|CREATE|DROP|ALTER)\s/i.test(p.sql));const u=db.usageSnapshot();assert.ok(u.rows_read<1800&&u.rows_written===0&&u.unknown_ops===0&&u.requests<18);return orig(p);};
const records={};
for(const [name,sql,args=[]] of [
 ['read_metadata','SELECT 1 AS read_only'],
 ['schema',"SELECT name,type,sql FROM sqlite_schema WHERE (type='table' AND name IN ('full_evidence_shadow_log','scan_runs','report2_evidence_source_cache','report2_market_snapshot_batch_v1')) OR (type='index' AND tbl_name IN ('full_evidence_shadow_log','scan_runs','report2_evidence_source_cache','report2_market_snapshot_batch_v1')) OR (type='trigger' AND tbl_name='full_evidence_shadow_log') LIMIT 60"],
 ['page_count','PRAGMA page_count'],['page_size','PRAGMA page_size'],['freelist_count','PRAGMA freelist_count'],
 ...['FIL-USDT','BR-USDT','ZEC-USDT'].map(c=>['recent_'+c,"SELECT full_evidence_id,shadow_id,contract_code,observed_ts,persisted_ts,LENGTH(stage392_proof_bundle_json) AS proof_bytes,LENGTH(evidence_compact_json) AS compact_bytes,LENGTH(relative_strength_json) AS relative_bytes,LENGTH(prior_htx_shadow_json) AS prior_bytes FROM full_evidence_shadow_log INDEXED BY idx_full_evidence_shadow_contract_ts WHERE contract_code=?1 ORDER BY observed_ts DESC LIMIT 3",[c]]),
 ['cache_sample',"SELECT source,asset_key,observed_ts,expires_ts,LENGTH(payload_json) AS payload_bytes FROM report2_evidence_source_cache WHERE source=?1 ORDER BY asset_key LIMIT 5",['COINPAPRIKA_HTX_IDENTITY']]
]){try{records[name]=await db.prepare(sql).bind(...args).all();}catch(e){records[name]={error:String(e.message).slice(0,240)};}}
fs.writeFileSync('audit-output/storage-read.json',JSON.stringify({schema:'report2-storage-readonly-v1',read_at:Date.now(),source_run:'1791235742342-1791235752702',records,usage:db.usageSnapshot(),sourceHTTP:0,MAIN:0,Telegram:0,storage_write:0},null,2));console.log(JSON.stringify({status:'BOUNDED_READ_ONLY_COMPLETE',usage:db.usageSnapshot(),sourceHTTP:0,MAIN:0,Telegram:0}));
